                ret.Add((LastModified, null));
                ret.Add((Unknown, null));
                ret.Add((Items == null ? DefaultOn : !Items.GetCrystal().CopyNothing, Items?.GetCrystal()));
                ret.Add((CLSZ, null));
                ret.Add((DNAM, null));
                ret.Add((MHDT, null));
                ret.Add((MNAM, null));
                ret.Add((ObjectBoundsMin != null ? ObjectBoundsMin.OnOverall : DefaultOn, ObjectBoundsMin?.GetCrystal()));
                ret.Add((CenterCell != null ? CenterCell.OnOverall : DefaultOn, CenterCell?.GetCrystal()));
                ret.Add((ObjectBoundsMax != null ? ObjectBoundsMax.OnOverall : DefaultOn, ObjectBoundsMax?.GetCrystal()));
                ret.Add((ONAM, null));
                ret.Add((RNAM, null));
                ret.Add((VISI, null));
                ret.Add((WCTR, null));
            }

